// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  DataTable,
  TableContainer,
  TableToolbar,
  TableToolbarContent,
  TableToolbarSearch,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
} from 'carbon-components-react';

// Minimal rows and headers for repro
typedef RowType = { id: string; name: string };

type HeaderType = { key: string; header: string };

const rows: RowType[] = [
  { id: '1', name: 'Alice' },
  { id: '2', name: 'Bob' },
  { id: '3', name: 'Carol' },
];

const headers: HeaderType[] = [
  { key: 'name', header: 'Name' },
];

function App() {
  return (
    <DataTable
      rows={rows}
      headers={headers}
      render={({ rows, headers, getHeaderProps, getRowProps, getTableProps, onInputChange }) => (
        <TableContainer title="DataTable" description="Repro: missing aria-label on search">
          <TableToolbar>
            {/* Attempt to provide a custom aria-label */}
            <TableToolbarSearch
              aria-label="Custom search label"
              onChange={onInputChange}
            />
            <TableToolbarContent>
              {/* any additional toolbar actions here */}
            </TableToolbarContent>
          </TableToolbar>
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                {headers.map(header => (
                  <TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id} {...getRowProps({ row })}>
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    />
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
